{"content":"import 'dart:async';

import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

import 'widgets/widgets.dart';

class CurrencyListPage extends StatefulWidget {
  const CurrencyListPage({super.key});

  @override
  State<CurrencyListPage> createState() => _CurrencyListPageState();
}

class _CurrencyListPageState extends State<CurrencyListPage> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final ValueNotifier<List<CurrencyModel>> _filteredCurrenciesNotifier;

  late final AnimationController _fadeController;

  Future<void>? _initFuture;

  List<CurrencyModel> _allCurrencies = [];

  int _currentPage = 0;
  bool _hasMore = false;
  bool _isLoadingMore = false;
  String _searchQuery = '';

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    _initAnimation();
    _refreshData();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _filteredCurrenciesNotifier.dispose();
    _fadeController.dispose();
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed && mounted) {
      _refreshData();
    }
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: Duration(milliseconds: 400),
      vsync: this,
    );
  }

  Future<void> _doLoad(int page) async {
    final currencyRepository = context.read<CurrencyRepository>();

    if (page == 0) {
      setState(() => _allCurrencies = []);
    }

    final CurrencyPage loaded = await currencyRepository.fetchRates(CurrencyPageRequest(base: 'EUR', page: page, pageSize: 20));

    if (!mounted) return;

    setState(() {
      if (page == 0) {
        _allCurrencies = loaded.items;
        _filteredCurrenciesNotifier = ValueNotifier(_filterList(''));
      } else {
        final List<CurrencyModel> existing = List.from(_allCurrencies);
        _allCurrencies = [...existing, ...loaded.items];
        _filteredCurrenciesNotifier.value = _filterList(_searchQuery);
      }

      _currentPage = page;
      _hasMore = loaded.hasMore;
    });

    currencyRepository.saveCurrencyList(loaded.items);
  }

  Future<void> _refreshData() async {
    if (!mounted) return;
    setState(() {
      _currentPage = 0;
      _hasMore = false;
      _isLoadingMore = false;
      _allCurrencies = [];
    });

    // Синхронно назначаем Future, а затем запускаем загрузку.
    // Сам _doLoad уже делает setState внутри себя.
    final Completer<void> completer = Completer();
    setState(() => _initFuture = completer.future.then((_) {
      if (mounted) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _fadeController.forward(); // запускаем анимацию после сборки
        });
      }
    }));

    await _doLoad(0);

    if (!completer.isCompleted) {
      completer.complete();
    }
  }

  List<CurrencyModel> _filterList(String query) {
    final String lowerQuery = query.toLowerCase();
    return _allCurrencies.where((CurrencyModel currency) {
      return currency.name.toLowerCase().contains(lowerQuery) || currency.symbol.toLowerCase().contains(lowerQuery);
    }).toList(growable: false);
  }

  void _filterCurrencies(String query) {
    setState(() => _searchQuery = query);
    if (_allCurrencies.isNotEmpty) {
      _filteredCurrenciesNotifier.value = _filterList(query);
    } else {
      _filteredCurrenciesNotifier.value = const [];
    }
  }

  Future<void> _loadMore() async {
    if (_isLoadingMore || !_hasMore || !mounted) return;
    setState(() => _isLoadingMore = true);
    final next = _currentPage + 1;
    await _doLoad(next).whenComplete(() {
      if (mounted) setState(() => _isLoadingMore = false);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.currencyRate)),
      body: FutureBuilder<void>(
        future: _initFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (!snapshot.hasData && !snapshot.hasError) return const SizedBox.shrink();

          return FadeTransition(
            opacity: _fadeController.view,
            child: Column(
              children: [
                Padding(
                  padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 22),
                  child: SearchView(onChanged: _filterCurrencies),
                ),
                Expanded(
                  child: ValueListenableBuilder<List<CurrencyModel>>(
                    valueListenable: _filteredCurrenciesNotifier,
                    builder: (BuildContext context, List<CurrencyModel> data, _) {
                      return ListView.builder(
                        itemCount: data.length + (_hasMore ? 1 : 0),
                        itemBuilder: (BuildContext context, int index) {
                          if (index >= data.length) {
                            return Padding(
                              padding: const EdgeInsets.all(16),
                              child: Center(
                                child: _isLoadingMore
                                    ? const SizedBox.square(dimension: 24, child: CircularProgressIndicator())
                                    : TextButton(
                                        onPressed: _loadMore,
                                        child: Text(context.loc.showMore),
                                      ),
                              ),
                            );
                          }

                          final CurrencyModel currency = data[index];

                          return Padding(
                            key: ValueKey(currency.id),
                            padding: index == 0 ? const EdgeInsets.only(top: 20) : const EdgeInsets.only(top: 10),
                            child: CurrencyCard(model: currency),
                          );
                        },
                        padding: const EdgeInsets.fromLTRB(22, 0, 22, 40),
                      );
                    },
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
