      await tester.pumpAndSettle();
      await tester.tap(find.byType(CurrencyCard).first);
      await tester.pumpAndSettle();

      expect(find.byType(CurrencyDetailPage), findsOneWidget);
    });

    testWidgets('should filter currencies when search text is entered', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      await tester.enterText(find.byType(TextField), 'Евро');
      await tester.pump();

      expect(find.byType(CurrencyCard), findsOneWidget);
    });

    testWidgets('should hide "show more" button when hasMore is false', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.byType(TextButton), findsNothing);
    });

    testWidgets('should show "show more" button when hasMore is true', (WidgetTester tester) async {
      final currencyItemsWithMore = List<CurrencyModel>.from(currencyItems);
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((Invocation invocation) async {
        final args = invocation.positionalArguments.first as CurrencyPageRequest;
        if (args.page == 0) {
          return CurrencyPage(items: currencyItemsWithMore, page: 0, hasMore: true);
        }
        return CurrencyPage(items: const <CurrencyModel>[], page: args.page, hasMore: false);
      });

      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});

      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.byType(TextButton), findsOneWidget);
      expect(find.text('Показать ещё'), findsOneWidget);
    });

    testWidgets('should refresh data when recreated (lifecycle resumed simulation)', (WidgetTester tester) async {
      int callCount = 0;
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((Invocation invocation) async {
        callCount++;
        return CurrencyPage(items: currencyItems, page: 0, hasMore: false);
      });

      // Первый запуск — создаём экран и ждём загрузки
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
        ),
      );

      await tester.pumpAndSettle();
      expect(callCount, 1);

      // Повторный pumpWidget с уникальным key — это симулирует создание нового State
      // (как при возврате на экран через BottomNavigationBar)
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(key: ValueKey('refresh')),
        ),
      );

      // Ждём завершения загрузки после "возврата" на экран
      await tester.pumpAndSettle();
      expect(callCount, 2);
    });
  });
}
